insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('BW', 'default', 'Botswana reference chart of accounts', '{}'::jsonb, true, 'companies', array['BW-BICA-IS', 'BW-BICA-SFP']::text[], null, 'There is no legal chart of accounts in Botswana. The Botswana Institute of Chartered Accountants (BICA) regulates the profession under the Accountants Act, 2010, and IFRS Accounting Standards are the reporting basis of public companies and non-exempt private companies; IFRS for SMEs is permitted for smaller entities. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements below, with the accounts a Botswana company actually keeps — VAT input and output tax, import VAT owed at the border, PAYE, withholding tax, pension contributions, training levy, excise and customs duty payable, and the irrecoverable VAT of s. 32 of the Value Added Tax Act, 2026.', 'ifrs-botswana')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

