insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('BW', 'BW-P-14', 'Purchase, standard rate 14 %, deductible', '{}'::jsonb, 'A local purchase at the general rate, used in the taxable activity of a registered person', 'percent', 14, 'purchase', 'domestic', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 55(1) — component C of the net VAT formula is the total input tax credit allowed for the period; s. 31 — the conditions for an input tax credit, including the tax invoice the supplier issues under s. 59; s. 55(2) — a credit not claimed in its period may be claimed up to six tax periods later (Category A and B) or twelve (Category C). Input tax is not allowed on every purchase (s. 32): a purchase of that kind takes code BW-P-14-ND.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-P-14-ND', 'Purchase, standard rate 14 %, input tax not deductible', '{}'::jsonb, 'A purchase whose input tax s. 32 denies — passenger vehicles, entertainment, club subscriptions', 'percent', 14, 'purchase', 'domestic', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 32(1) — no input tax credit is allowed on (a) the acquisition of a passenger vehicle (a road vehicle for nine or fewer seated persons) unless the person deals in or hires such vehicles or supplies it to a customer for promotion; (c) goods or services acquired for entertainment (food, beverages, recreation, tobacco, hospitality), with three exceptions; (d) fees or subscriptions for membership of a sporting, social or recreational club. The tax follows the expense to account 6530. Half of the cost of repair and maintenance of such a vehicle is denied (s. 32(1)(b)): the pack has no code for a split purchase and the README records the gap.', null, null, 115, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-P-EX', 'Purchase, exempt', '{}'::jsonb, 'An exempt supply bought for the business — a financial service, bank charges, a residential lease', 'percent', 0, 'purchase', 'exempt', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 9 and Schedule 2 — an exempt supply bears no VAT, so there is no input tax to deduct. The return carries no row for an exempt purchase.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-P-IMP', 'Import of goods, VAT paid at the border', '{}'::jsonb, 'VAT charged on a taxable import, paid at the time of import and claimed as input tax', 'percent', 14, 'purchase', 'import', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 7(1)(b) and (7) — VAT is levied on a taxable import by any person, the liability arises at the time of the import and is payable by the importer at that time (s. 66(3), s. 67(1)(c)); s. 55(3) — a registered importer claims the credit no later than the following tax period; s. 10 and Schedule 3 list the exempt imports. The tax is owed at the border and not to the supplier, so it waits on 2125 until the import declaration is settled. Imports from Namibia, Lesotho, South Africa and Eswatini (the Southern African Customs Union partners) are not special in the Act: VAT is charged on entry like any other import (Schedule 3 only names them for allowances and returned goods).', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-P-RC-SVC', 'Remote service received, reverse charged', '{}'::jsonb, 'A service supplied remotely from outside Botswana to a registered person, who accounts for the VAT and recovers it', 'percent', 14, 'purchase', 'foreign_services_received', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 7(1)(c), (2)(b) and (8) — VAT is levied on a reverse charged supply made to a registered person, the liability arises at the time of the supply and the recipient accounts for it; s. 55(1) — component B of the net VAT formula is the reverse charged VAT for the period, and component C allows the matching input tax credit where the service is used in the taxable activity; s. 59(4) — the registered recipient prepares a recipient-created tax invoice at the time of supply; s. 64 — it notifies the supplier in writing that it is a registered person. Reporting by registered persons starts with the August/September 2026 period (Category A), the September/October period (Category B) and the August 2026 return (Category C), per the BURS guidance note of September 2026. A service used for exempt supplies, or in part, is not fully recoverable: the README records the gap.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'reverse-charge-guidance', null, null, null, null),
  ('BW', 'BW-P-Z', 'Purchase, zero-rated (local)', '{}'::jsonb, 'A local purchase of a good Schedule 1 taxes at nil, from a registered supplier', 'percent', 0, 'purchase', 'domestic', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 8(1) and Schedule 1, Part III — there is no input tax to deduct on a supply taxed at nil; the value is reported in its own row.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-S-14', 'Sale, standard rate 14 %', '{}'::jsonb, 'The general rate on a taxable supply made in Botswana', 'percent', 14, 'sale', 'domestic', date '2026-07-01', null, 'Value Added Tax Act, 2026 (Act No. 15 of 2026), s. 7(1)(a) and (2)(b) — VAT is levied on a taxable supply made by a registered person at 14 per cent for any taxable supply that is not zero-rated; s. 7(3) — the tax is the rate applied to the value of the supply. The Act commenced on 1 July 2026 and re-enacts the 14 % rate that applied before it; this pack''s tax codes start at the commencement date. A public notice of 9 July 2026 repeats that food outside the zero-rated list bears 14 %.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply Schedule 2 lists: financial services, residential lease, education, public medical facilities, public transport, precious metals', 'percent', 0, 'sale', 'exempt', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 9 and Schedule 2, para 1 — (a) financial services as defined; (b) a precious metal; (c) services specified in the regulations by a public (Government operated or aided) medical facility; (d) donated goods or services of a non-profit body; (e) education services of a school, technical college, university or adult-education institution; (f) public transport services regulated by Government; (i) the lease of residential premises, other than a lease of less than 45 days; also homeowners'' association services and nominal-consideration supplies of Government entities and non-profit bodies. An exempt supplier is not entitled to input tax on what it uses to make the supply. A supply that is both zero-rated and exempt is zero-rated (s. 9(2)). Private medical services are taxable under the Act but the charging of VAT on them was suspended by BURS on 30 July 2026; this code is not for them and the README records the gap.', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-S-Z-DOM', 'Sale, zero-rated (domestic — basic foodstuffs, fuel, prescription medicines, fertilisers)', '{}'::jsonb, 'A local supply the First Schedule taxes at nil without it leaving Botswana', 'percent', 0, 'sale', 'domestic', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 8(1) and Schedule 1, Part III, para 1 — (b) and (c) the foodstuffs in their natural state the Schedule names (maize and sorghum meal, millet, wheat, sugar, brown bread, fresh vegetables and fruit of the listed headings, rice, samp, bread flour, cooking oil), liquid petroleum gas, infant formula, baby diapers, sanitary pads and tampons, pesticides, fertilisers and the first 5 000 litres of water a month to a residence; (d) the listed agricultural implements and tractors; (e) petrol, diesel and illuminating paraffin; (f) condoms; (g) prescription medicines for humans. Public notice of 9 July 2026: any food not on the list bears 14 %. The going-concern transfer of para 1(a) is also zero-rated but is reported on the same row; the customs-heading conditions are the Act''s and are not applied by the pack.', 'Z', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('BW', 'BW-S-Z-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'An export of goods, or a service for use or consumption outside Botswana, or international transport', 'percent', 0, 'sale', 'export', date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 8(1) and Schedule 1, Part I — a supply of goods the supplier has entered for export to an export country and has exported, or that the Commissioner General is satisfied were exported (para 1(a), (b)); Part II — a supply of services for use or consumption in an export country, evidenced by documentary proof, and international transport services (para 1(a), (c)); s. 8(2) — the registered person keeps the documentary proof the Commissioner General accepts (Value Added Tax Regulations, 2026, regs 8 to 11). A zero-rated supply is a taxable supply: input tax stays deductible. Services directly in relation to immovable property in Botswana and inbound tourism products are excluded from Part II.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

