insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BW', 'BW-VAT-RETURN', 'Value Added Tax return', array['month', 'bimonth']::declaration_period[], null, date '2026-07-01', null, 'Value Added Tax Act, 2026, s. 54 — a registered person''s tax period is one month (Category C: taxable supplies above P12 million, by authorisation, or by notice for regular default) or two months (Category A, ending January, March, May, July, September and November; Category B, ending February, April, June, August, October and December, allocated by the Commissioner General); s. 65(1) — a return is lodged for every period whether or not VAT is payable. Category A periods run December–January, February–March and so on; Ekwo''s `bimonth` is anchored on January (January–February…) and so fits Category B only, which the README records as a gap. The approved return form (VAT 002.1) could not be opened, so only the components of the s. 55(1) formula are sourced; the value rows are this pack''s own. No cadence is declared as the default because it depends on the taxpayer''s category.', true,'day_of_month_after_period'::filing_deadline_rule, 28, null, 'Value Added Tax Act, 2026, s. 65(1) — a registered person lodges the return within 28 days after the end of the tax period, and s. 66(1) — the VAT is payable by the same date. Twenty-eight days after the last day of any month falls on the 28th of the next month. Penalties and the interest of Schedule 5, para 6 (1 per cent a month) are not modelled.', 'vat-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('BW', 'BW-VAT-RETURN', 'ZE', 'base', 'Zero-rated supplies — exports', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, Schedule 1, Parts I and II — the value of exports of goods and services and international transport. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'ZL', 'base', 'Zero-rated supplies — local', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, Schedule 1, Part III — the value of local supplies taxed at nil. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'EX', 'base', 'Exempt supplies', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, Schedule 2 — the value of exempt supplies. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '1S', 'base', 'Standard-rated supplies — value', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 7(2)(b) — the sales on which output tax is charged at 14 %. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '1S', 'tax', 'Output tax on standard-rated supplies', '{}'::jsonb, 45, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1), component A — the output tax receivable on taxable supplies made in the period, net of credit notes issued.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'RC', 'base', 'Reverse charged supplies — value', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 7(1)(c) — the value of remote services received on which the registered recipient accounts for the VAT. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'RC', 'tax', 'Reverse charged VAT', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1), component B — the reverse charged VAT the registered person is liable for in the period.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'OUT', 'total', 'Output VAT (A + B)', '{}'::jsonb, 60, null, array['1S:tax', 'RC:tax']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1) — components A and B of the net VAT formula: output tax on supplies plus reverse charged VAT.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', 'ZP', 'base', 'Zero-rated purchases — value', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, Schedule 1 — the value of local purchases taxed at nil. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '2', 'base', 'Standard-rated local purchases — value', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 31 — the purchases on which input tax is claimed. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '2', 'tax', 'Input tax on local purchases', '{}'::jsonb, 85, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1), component C — input tax credits allowed on local acquisitions, net of credits received.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '3', 'base', 'Imports of goods — value', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 7(1)(b) — the value of taxable imports on which VAT was paid at the border. A reporting row of this pack: the approved return form could not be opened, so its box numbers are not reproduced.', 'vat-act'),
  ('BW', 'BW-VAT-RETURN', '3', 'tax', 'Input tax on imports', '{}'::jsonb, 95, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1) and (3) — input tax credit on taxable imports, claimed in the period of the import or the next.', 'vat-act'),
