  ('BW', 'BW-VAT-RETURN', 'IN', 'total', 'Input tax credits (C)', '{}'::jsonb, 100, null, array['2:tax', '3:tax', 'RCI:tax']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, 2026, s. 55(1), component C — the total input tax credit allowed for the period.', 'vat-act'),
