update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax Act, 2026, s. 59(7) and Schedule 4 — a tax invoice carries an individualised serial number and the date it is issued, together with the words "original tax invoice" and the VAT registration numbers of supplier and recipient. The law asks for an individualised serial number and not for a series with no gap, which is why `numbering` is `sequential`.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value Added Tax Act, 2026, s. 7(4) — the liability for VAT on a taxable supply arises at the time of the supply, and the Act''s time-of-supply rules (invoice, payment, delivery) are not reproduced in the closed vocabulary; `earliest_of_delivery_or_payment` is the nearest value and the gap is recorded in this pack''s README.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Tax Administration Act, 2026, s. 15 — a taxpayer who supplies goods, renders services or receives payment for them shall issue an electronic invoice using an electronic billing system, and s. 59(8) and s. 60(4) of the Value Added Tax Act, 2026 say the same of a registered person''s tax invoices, credit notes and debit notes; s. 100 of the Tax Administration Act fixes a penalty of P10 000 for each month of failure once the person is required to use the system. The system is a billing system approved by the Botswana Unified Revenue Service that reports to the administration, not a peer-to-peer exchange: Botswana has no Peppol authority, no published profile and no scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none` in Ekwo''s vocabulary. The date from which the system is binding is set by the Tax Administration Regulations, 2026 (reported by secondary commentary as nine months after commencement, around 1 April 2027), a text this pack could not open, so `mandatory_from` is null. The gap is recorded in this pack''s README and the socle is not patched to fit it.',
  einvoice_source_key           = 'tax-administration-act',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'BW';
